SELECT path, header_status, group_number, mount_status,
       os_mb, ROUND(os_mb/1024,1) AS os_gb, total_mb
FROM   v$asm_disk WHERE path LIKE 'AFD:%' AND group_number = 0;

-- bigfile
ALTER TABLESPACE <ts> RESIZE <tamanho>;

-- smallfile no MAXSIZE, ainda abaixo do teto do formato
ALTER DATABASE DATAFILE <file_id> AUTOEXTEND ON NEXT 512M MAXSIZE 32G;

-- smallfile ja no teto: arquivo novo
ALTER TABLESPACE <ts>
  ADD DATAFILE '+<DISKGROUP>' SIZE 32G AUTOEXTEND ON NEXT 512M MAXSIZE 32G;
